        PartDefinition linkUpper = linkLower.addOrReplaceChild("link_upper", CubeListBuilder.create()
                        .texOffs(50, 11).addBox(-3.0F, 0.0F, -1.0F, 1.0F, 5.0F, 2.0F)
                        .texOffs(56, 11).addBox(2.0F, 0.0F, -1.0F, 1.0F, 5.0F, 2.0F)
                        .texOffs(62, 11).addBox(-3.0F, 1.0F, -2.0F, 1.0F, 3.0F, 1.0F)
                        .texOffs(66, 11).addBox(2.0F, 1.0F, -2.0F, 1.0F, 3.0F, 1.0F),
                PartPose.offset(0.0F, 10.0F, 0.0F));
        PartDefinition blade = linkUpper.addOrReplaceChild("blade", CubeListBuilder.create()
                        .texOffs(70, 11).addBox(-2.0F, -4.0F, -2.0F, 4.0F, 4.0F, 3.0F)
                        .texOffs(84, 11).addBox(-1.0F, -6.0F, -1.0F, 2.0F, 2.0F, 2.0F)
                        .texOffs(92, 11).addBox(-1.0F, -4.0F, 1.0F, 2.0F, 2.0F, 1.0F)
                        .texOffs(98, 11).addBox(-1.0F, 0.0F, -1.0F, 2.0F, 14.0F, 2.0F)
                        .texOffs(106, 11).addBox(-1.0F, 2.0F, -2.0F, 2.0F, 10.0F, 1.0F),
                PartPose.offset(0.0F, 5.0F, 0.0F));
        PartDefinition edge = blade.addOrReplaceChild("edge", CubeListBuilder.create()
                        .texOffs(112, 11).addBox(-0.5F, 0.0F, -1.0F, 1.0F, 22.0F, 2.0F)
                        .texOffs(118, 11).addBox(-0.5F, 1.0F, 1.0F, 1.0F, 1.0F, 1.0F)
                        .texOffs(122, 11).addBox(-0.5F, 3.0F, 1.0F, 1.0F, 1.0F, 1.0F)
                        .texOffs(0, 35).addBox(-0.5F, 5.0F, 1.0F, 1.0F, 1.0F, 1.0F)
                        .texOffs(4, 35).addBox(-0.5F, 7.0F, 1.0F, 1.0F, 1.0F, 1.0F)
                        .texOffs(8, 35).addBox(-0.5F, 9.0F, 1.0F, 1.0F, 1.0F, 1.0F)
                        .texOffs(12, 35).addBox(-0.5F, 22.0F, -1.0F, 1.0F, 2.0F, 1.0F)
                        .texOffs(16, 35).addBox(-0.5F, 24.0F, -1.0F, 1.0F, 1.0F, 1.0F),
                PartPose.offset(0.0F, 14.0F, 0.0F));
